  "league.rank.tableAria": "Current rank and name",
  "league.description.sibenikBrief": "Welcome to the Šibenik Trail League—a series of trail-running races created to bring people together through sport, nature and the landscapes of the Šibenik region. Our races are open to runners of different ages and experience levels.",
  "league.description.sibenikAbout": "We created the Ši Trail League to make trail running accessible, strengthen our local sporting community and introduce runners to the remarkable natural diversity of Šibenik-Knin County. Throughout the season, our races move between the coast and the Dalmatian hinterland. The routes explore areas around Vrpolje, the Torak spring and Goriš, the slopes of Trtar, and the coastal settlements of Raslina and Zaton. Together, these locations reveal a landscape of narrow trails, gravel roads, rocky climbs, viewpoints, canyons and paths beside the sea. Each round has its own character. Some routes are fast and welcoming to recreational runners, while others feature technical terrain and more demanding elevation. Shorter and longer route options allow participants of different ages and experience levels to take part, compete and progress throughout the season. Our goal goes beyond race results. We want every race to encourage an active lifestyle, responsible enjoyment of nature and respect for the places through which we run. Just as importantly, we want to create a friendly meeting point where runners, volunteers, families and local communities can share the experience of a day outdoors. For us, Šibenik is more than the host city—it is the starting point for discovering the coast, hinterland and lesser-known trails of the wider region. Every race is an invitation to explore a different side of Dalmatia, away from the usual tourist routes, one trail at a time.",
