  "rewards.planner.error": "Provjeri unose: svaka skupina postotaka mora imati zbroj 100, MON prihvaća do 18 decimalnih mjesta, a ponderi nagrada moraju biti pozitivni cijeli brojevi od najvećeg prema najmanjem.",
  "rewards.planner.presets": "Unutarnje podjele i krivulje nagrada predložene su postavke. Službene kategorije i točne iznose organizator još treba odobriti.",
  "rewards.planner.review": "Pregled od 24 sata",
  "rewards.planner.reviewHelp": "Jedno razdoblje pregleda nakon objave rezultata i potpunog prijedloga raspodjele. Bez dodatnog uzastopnog čekanja.",
