  "rewards.programme.detailLink": "Prikaži odabranu raspodjelu",
  "rewards.programme.rule.programme": "Fond od 10.000 testnih MON dijeli se na 60% za pet kola i 40% za ligaške nagrade. Mrežne naknade plaćaju se zasebno. Ovo je plan fonda, a ne stanje novčanika.",
  "rewards.programme.rule.race": "Svako od pet kola dobiva jednak dio. Završena kola mogu se isplatiti zasebno; peto ih kolo ne blokira.",
  "rewards.programme.rule.league": "Prva ligaška raspodjela obuhvaća kola 1–5. Udaljenosti natjecatelja pripada 75%, a završecima utrka za klubove 25%, nakon odobrenja rezultata petog kola.",
  "rewards.programme.rule.round": "Fond svakog kola dijeli se u omjeru 4:1:1 na postolja natjecatelja, potvrđene rekorde i uspješnost klubova. Nedostatak dokaza ne pretvara se u izmišljenu nagradu.",
  "rewards.programme.rule.podium": "Prva tri mjesta svake odobrene službene kategorije dijele 50%, 30% i 20% njezina fonda. Fondovi kategorija i rezultati najprije trebaju odobrenje.",
  "rewards.programme.rule.record": "Nagradu donosi samo strogo poboljšan, potvrđen i usporediv prethodni rekord rute. Bez odobrenog prethodnog rekorda ili novog rekorda neiskorišteni dio ostaje rezerviran.",
  "rewards.programme.rule.clubPerformance": "Klupski poredak koristi tri najbolja objavljena doprinosa klupskim bodovima s obje duljine. Klub zadržava svoj dio i prije potvrde klupskog novčanika.",
  "rewards.programme.rule.athleteDistance": "Raspodjela je razmjerna službenim metrima prihvatljivih završenih utrka natjecatelja u kolima 1–5, a ne GPS zapisima. Nepreuzeti profili i natjecatelji bez novčanika zadržavaju svoj dio.",
  "rewards.programme.rule.clubFinishes": "Raspodjela je razmjerna prihvatljivim završecima utrka za svaki klub u kolima 1–5. Nepotvrđen klupski novčanik zadržava isplatu, ali ne oduzima ostvareni dio.",
  "rewards.programme.evidence.programme": "Odobrene snimke izvora, povezivanje kola i zapisi izračuna moraju povezati sportske rezultate s nagradama prije isplate.",
  "rewards.programme.evidence.round": "Objavljeni završeci utrka, službene kategorije, klupski bodovi i usporedivi rekordi moraju biti odobreni i povezani sa svakom nagradom.",
  "rewards.programme.evidence.league": "Za prvu ligašku raspodjelu potrebne su odobrene snimke svih pet kola. Svaki završetak utrke mora pokazati doprinos metrima ili klupskom udjelu.",
  "rewards.programme.evidence.replacement": "Peto kolo zamjenjuje otkazani Zlarin. Datum Šubićevca i povezivanje utrka i ruta još nisu potvrđeni; ne smiju se preuzeti Zlarinovi identifikatori ni prethodni rekordi.",
  "rewards.programme.evidence.podium": "Svaka nagrada mora biti povezana sa službenim rezultatom, kategorijom i osvojenim mjestom.",
  "rewards.programme.evidence.record": "Svaka nagrada mora biti povezana s novim vremenom, potvrđenim prethodnim rekordom i odobrenjem usporedivosti rute.",
  "rewards.programme.evidence.clubPerformance": "Svaka klupska nagrada mora pokazati uračunate natjecatelje i njihov doprinos službenim klupskim bodovima.",
  "rewards.programme.evidence.athleteDistance": "Svaki udio natjecatelja mora navesti prihvatljive završene utrke i službene metre, uključujući nepreuzete profile.",
  "rewards.programme.evidence.clubFinishes": "Svaki klupski udio mora navesti prihvatljive završene utrke i zabilježeno predstavljanje kluba korišteno u izračunu.",
