  "rewards.canary.v3Policy": "Novi model provjere: organizator unaprijed određuje rok za prigovore na portalu. Konačni rezultati i točna raspodjela moraju biti odobreni prije aktivacije, bez dodatnog obveznog čekanja na lancu. Ovaj sintetički pokus izričito koristi rok od nula sati.",
  "rewards.canary.v2Policy": "Raniji pokus: ovaj zasebni ugovor zadržava izvorni nepromjenjivi rok od 24 sata na lancu. Promjena prikaza ne premješta sredstva niti mijenja ugovore.",
  "rewards.canary.v3NotApproved": "Konačna objava i odobrenje raspodjele još nisu zabilježeni u ovom ugovoru.",
