  "rewards.canary.v3Trust": "Ugovor se oslanja na operaterovu potvrdu konačnih rezultata; ne može sam provjeriti sportske rezultate ni prigovore. Aktivacija je zasebna transakcija i ne isplaćuje nagrade automatski.",
  "rewards.canary.executionBoundary": "Planirani udjeli odvojeni su od stvarnih iznosa iznad. Financiranje i aktivacija prolaze kroz kontrolirani operaterski postupak uz provjeru izvornog koda; ova stranica ne šalje transakcije. Prije isplate i dalje su potrebni dokaz upravljanja novčanikom i pristanak primatelja.",
