  "rewards.wallet.title": "Tvoj novčanik za nagrade",
  "rewards.wallet.help": "Već koristiš novčanik? Možeš potvrditi da kontroliraš njegovu adresu. Time se ne odabire adresa za isplatu, ne potvrđuju dob ni mogućnost oporavka i ne odobrava isplata nagrade.",
  "rewards.wallet.noSecrets": "Nikad ne unosi privatni ključ ni frazu za oporavak u RacesOn. Ova provjera ne traži transakciju ni mrežnu naknadu.",
