  "rewards.wallet.noWallet": "Nemam novčanik",
  "rewards.wallet.noWalletHelp": "Novčanik ti nije potreban da tvoj pripadajući udio ostane rezerviran. Kada je postavljanje novčanika unutar ove demonstracije omogućeno, ovdje ga možeš stvoriti po svom izboru. RacesOn ne stvara ni čuva privatne ključeve natjecatelja. Nastavi koristiti postojeći profil.",
  "rewards.privy.title": "Privy novčanik za nagrade",
  "rewards.privy.help": "Koristi svoj demonstracijski račun uz Privy. Stvaranje novčanika nije obvezno i ne preuzima nagrade niti šalje novac. Nikada ne dijeli privatni ključ ili tajnu za oporavak s RacesOnom.",
  "rewards.privy.unconfigured": "Novčanici u aplikaciji još nisu omogućeni u ovom okruženju. Tvoj udio nagrade ostaje rezerviran; postojeći novčanik preglednika i dalje je podržan.",
