  "league.rank.points": "Bodovi",
  "league.rank.interactiveAria": "Interaktivno kretanje u ligi. Krivulje koriste poredak na lijevoj osi, s prvim mjestom na vrhu. Numerirani krugovi prikazuju poziciju nakon svakog kola. {details}. Fokusiraj ili dodirni numerirani krug za detalje.",
  "league.rank.tableAria": "Trenutačni poredak i ime",
  "league.description.sibenikBrief": "Dobro došli u Šibensku Trail Ligu — seriju trail utrka koja sportom, prirodom i krajolicima šibenskog kraja povezuje ljude. Naše su utrke otvorene trkačima različite dobi i razine iskustva.",
  "league.description.sibenikAbout": "Ši Trail Ligu pokrenuli smo kako bismo trail trčanje učinili dostupnim, ojačali lokalnu sportsku zajednicu i trkačima predstavili iznimnu prirodnu raznolikost Šibensko-kninske županije. Tijekom sezone naše se utrke izmjenjuju između obale i dalmatinskog zaleđa. Rute vode područjima Vrpolja, izvora Torak i Goriša, obroncima Trtra te obalnim mjestima Raslina i Zaton. Zajedno otkrivaju krajolik uskih ruta, makadama, kamenitih uspona, vidikovaca, kanjona i putova uz more. Svako kolo ima svoj karakter. Neke su rute brze i pristupačne rekreativcima, dok druge donose tehnički zahtjevan teren i veći uspon. Kraće i duže rute omogućuju sudjelovanje, natjecanje i napredovanje trkačima različite dobi i iskustva tijekom cijele sezone. Naš cilj nadilazi rezultate utrka. Želimo da svaka utrka potiče aktivan život, odgovorno uživanje u prirodi i poštovanje prostora kroz koji trčimo. Jednako nam je važno stvoriti prijateljsko mjesto susreta na kojem trkači, volonteri, obitelji i lokalne zajednice mogu podijeliti doživljaj dana provedenog na otvorenom. Za nas je Šibenik više od grada domaćina — on je polazište za otkrivanje obale, zaleđa i manje poznatih ruta šire regije. Svaka je utrka poziv da se upozna drugačija strana Dalmacije, dalje od uobičajenih turističkih ruta, rutu po rutu.",
